presets.css:
/* ============================================================
   Puff · 壁纸 + 透明顶栏 + 双气泡/转账卡贴图（新素材）
   仅使用 Puff 模板真实类名
   ============================================================ */

/* 0. 壁纸 */
.chat-thread-bg {
  background-image: url("https://cdn.jsdelivr.net/gh/idikale163-source/assets-bed-4775@main/uploads/20260930_180056_6b30.png") !important;
  background-size: cover !important;
  background-position: center !important;
  background-repeat: no-repeat !important;
  background-attachment: fixed !important;
  background-color: transparent !important;
}
.chat-thread-bg::after {
  background: transparent !important;
}

/* 1. 顶栏胶囊透明 */
.chat-thread-pill {
  background: transparent !important;
  background-image: none !important;
  background-color: transparent !important;
  border: none !important;
  box-shadow: none !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  color: var(--ink);
}
.chat-thread-pill .chat-back,
.chat-thread-head-more,
.chat-thread-head-xinsheng {
  color: var(--ink);
  background: transparent;
}

/* 2. 对方气泡：5occ.png */
.chat-msg.is-them .chat-bubble {
  position: relative !important;
  box-sizing: border-box !important;
  width: fit-content !important;
  min-width: 35px !important;
  min-height: 28px !important;
  max-width: calc(100vw - 60px) !important;
  height: auto !important;
  margin-left: 4px !important;
  margin-right: auto !important;
  margin-top: 5px !important;
  background: transparent !important;
  background-color: transparent !important;
  border-style: solid !important;
  border-color: transparent !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  overflow: visible !important;
  border-width: 4px 4px 4px 5px !important;
  border-image-source: url("https://cdn.jsdelivr.net/gh/idikale163-source/assets-bed-4775@main/uploads/20261005_233957_5occ.png") !important;
  border-image-slice: 32 34 31 36 fill !important;
  border-image-repeat: stretch !important;
  border-image-width: 3 !important;
  padding: 4px 4px 6px 9px !important;
  color: #000000 !important;
  -webkit-text-fill-color: #000000 !important;
  line-height: 1.35 !important;
  word-break: break-word !important;
  overflow-wrap: anywhere !important;
  z-index: 1 !important;
}
.chat-msg.is-them .chat-bubble * {
  background-color: transparent !important;
  color: #000000 !important;
  -webkit-text-fill-color: #000000 !important;
}

/* 3. 我方气泡：tcsp.png */
.chat-msg.is-me .chat-bubble {
  position: relative !important;
  box-sizing: border-box !important;
  width: fit-content !important;
  min-width: 35px !important;
  min-height: 28px !important;
  max-width: calc(100vw - 60px) !important;
  height: auto !important;
  margin-left: auto !important;
  margin-right: 4px !important;
  margin-top: 5px !important;
  background: transparent !important;
  background-color: transparent !important;
  border-style: solid !important;
  border-color: transparent !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  overflow: visible !important;
  border-width: 4px 5px 5px 4px !important;
  border-image-source: url("https://cdn.jsdelivr.net/gh/idikale163-source/assets-bed-4775@main/uploads/20261005_234000_tcsp.png") !important;
  border-image-slice: 31 39 37 33 fill !important;
  border-image-repeat: stretch !important;
  border-image-width: 3 !important;
  padding: 5px 5px 5px 8px !important;
  color: #000000 !important;
  -webkit-text-fill-color: #000000 !important;
  line-height: 1.35 !important;
  word-break: break-word !important;
  overflow-wrap: anywhere !important;
  z-index: 1 !important;
}
.chat-msg.is-me .chat-bubble * {
  background-color: transparent !important;
  color: #000000 !important;
  -webkit-text-fill-color: #000000 !important;
}

/* 气泡文本净化 */
.chat-bubble-primary {
  position: relative !important;
  display: block !important;
  box-sizing: border-box !important;
  width: 100% !important;
  max-width: 100% !important;
  min-width: 0 !important;
  margin: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  line-height: 1.35 !important;
  white-space: pre-wrap !important;
  word-break: break-word !important;
  overflow-wrap: anywhere !important;
  text-align: left !important;
}
.chat-bubble-primary p,
.chat-bubble-primary span,
.chat-bubble-primary div,
.chat-bubble-primary blockquote,
.chat-bubble-primary strong,
.chat-bubble-primary em,
.chat-bubble-primary a {
  box-sizing: border-box !important;
  width: auto !important;
  max-width: 100% !important;
  min-width: 0 !important;
  margin-left: 0 !important;
  margin-right: 0 !important;
  background-color: transparent !important;
  white-space: pre-wrap !important;
  word-break: break-word !important;
  overflow-wrap: anywhere !important;
}
.chat-bubble-primary p,
.chat-bubble-primary > div {
  margin-top: 0 !important;
  margin-bottom: 3px !important;
}
.chat-bubble-primary p:last-child,
.chat-bubble-primary > div:last-child {
  margin-bottom: 0 !important;
}

/* 4. 转账卡：默认 5occ.png */
.puff-transfer {
  position: relative !important;
  box-sizing: border-box !important;
  overflow: visible !important;
  background: transparent !important;
  background-color: transparent !important;
  border-style: solid !important;
  border-color: transparent !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  border-image-repeat: stretch !important;
  border-width: 8px 8px 6px 8px !important;
  border-image-source: url("https://cdn.jsdelivr.net/gh/idikale163-source/assets-bed-4775@main/uploads/20261005_233957_5occ.png") !important;
  border-image-slice: 32 34 31 36 fill !important;
  border-image-width: 3 !important;
  padding: 6px 14px 6px 14px !important;
}
.puff-transfer * {
  text-shadow: none !important;
  color: #000000 !important;
  -webkit-text-fill-color: #000000 !important;
}
.puff-transfer > div {
  background: transparent !important;
  background-color: transparent !important;
  border: none !important;
}
.puff-transfer > div,
.puff-transfer > div > div,
.puff-transfer > div > div > div {
  background: transparent !important;
  background-image: none !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  outline: none !important;
}

/* 用户侧转账卡：tcsp.png */
.chat-msg.is-me .puff-transfer {
  border-width: 8px 8px 7px 8px !important;
  border-image-source: url("https://cdn.jsdelivr.net/gh/idikale163-source/assets-bed-4775@main/uploads/20261005_234000_tcsp.png") !important;
  border-image-slice: 31 39 37 33 fill !important;
  border-image-width: 3 !important;
  padding: 6px 14px 6px 14px !important;
}
.chat-msg.is-me .puff-transfer * {
  text-shadow: none !important;
  color: #000000 !important;
  -webkit-text-fill-color: #000000 !important;
}

/* 5. 夜间模式：整体压暗（Puff 用 data-theme） */
html[data-theme="dark"] .chat-msg.is-them .chat-bubble,
html[data-theme="dark"] .chat-msg.is-me .chat-bubble,
html[data-theme="dark"] .puff-transfer {
  filter: brightness(0.55) !important;
}
html[data-theme="dark"] .chat-msg.is-them .chat-bubble *,
html[data-theme="dark"] .chat-msg.is-me .chat-bubble *,
html[data-theme="dark"] .puff-transfer * {
  color: #000000 !important;
  -webkit-text-fill-color: #000000 !important;
}
